// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.VF;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.assertEvaluationError;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.date;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.dt;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.str;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.time;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.junit.jupiter.api.Test;

/**
 * Edge cases of {@code dtf:dateFormat(dt, pattern [, locale])} and {@code dtf:parseDate(s, pattern [, locale])}.
 */
class DateFormatParseEdgeCaseTest {

	private final DateFormat dateFormat = new DateFormat();
	private final ParseDate parseDate = new ParseDate();

	@Test
	void invalidPatternsAreAnEvaluationErrorAndQuotedTextIsLiteral() {
		for (String pattern : List.of("yyyy-MM-dd ii", "jjjj", "yyyy-MM-dd 'unterminated", "yyyy-MM-dd {")) {
			assertEvaluationError("format " + pattern,
					() -> dateFormat.evaluate(VF, dt("2024-05-17T10:11:12Z"), str(pattern)));
			assertEvaluationError("parse " + pattern, () -> parseDate.evaluate(VF, str("2024-05-17"), str(pattern)));
		}
		assertThat(dateFormat.evaluate(VF, dt("2024-05-17T10:11:12Z"), str("yyyy-MM-dd'T'HH:mm:ss")))
				.isEqualTo(str("2024-05-17T10:11:12"));
		assertThat(parseDate.evaluate(VF, str("2024-05-17T10:11:12"), str("yyyy-MM-dd'T'HH:mm:ss")))
				.isEqualTo(dt("2024-05-17T10:11:12"));
		assertThat(dateFormat.evaluate(VF, date("2024-05-17"), str("'year' yyyy 'o''clock'")))
				.isEqualTo(str("year 2024 o'clock"));
	}

	@Test
	void patternLettersWithoutAMatchingFieldAreAnEvaluationError() {
		assertEvaluationError("date with seconds", () -> dateFormat.evaluate(VF, date("2024-05-17"), str("HH:mm:ss")));
		assertEvaluationError("date with hour",
				() -> dateFormat.evaluate(VF, date("2024-05-17"), str("yyyy-MM-dd HH")));
		assertEvaluationError("time with year", () -> dateFormat.evaluate(VF, time("10:11:12"), str("yyyy")));
		assertEvaluationError("no offset to print",
				() -> dateFormat.evaluate(VF, dt("2024-05-17T10:11:12"), str("HH:mmXXX")));
		assertThat(dateFormat.evaluate(VF, date("2024-05-17+02:00"), str("yyyy-MM-ddXXX")))
				.isEqualTo(str("2024-05-17+02:00"));
		// pins current behaviour: a date that carries a timezone is formatted as midnight in that timezone, so time
		// letters print 00:00 instead of raising an error
		assertThat(dateFormat.evaluate(VF, date("2024-05-17+02:00"), str("HH:mm"))).isEqualTo(str("00:00"));
	}

	@Test
	void localeAffectsMonthNames() {
		Literal may = date("2024-05-17");
		assertThat(dateFormat.evaluate(VF, may, str("MMMM"), str("fr"))).isEqualTo(str("mai"));
		assertThat(dateFormat.evaluate(VF, may, str("MMMM"), str("de"))).isEqualTo(str("Mai"));
		assertThat(dateFormat.evaluate(VF, may, str("MMMM"), str("en"))).isEqualTo(str("May"));
		assertThat(dateFormat.evaluate(VF, may, str("EEEE d MMMM yyyy"), str("nb-NO")))
				.isEqualTo(str("fredag 17 mai 2024"));
		assertThat(parseDate.evaluate(VF, str("17 mai 2024"), str("d MMMM yyyy"), str("fr"))).isEqualTo(may);
		assertEvaluationError("french name in english",
				() -> parseDate.evaluate(VF, str("17 mai 2024"), str("d MMMM yyyy"), str("en")));
		// pins current behaviour: without a locale the root locale is used, and an unknown language tag falls back
		// to the same root data rather than raising an error
		Literal root = dateFormat.evaluate(VF, may, str("MMMM"));
		assertThat(root).isEqualTo(str("May"));
		assertThat(dateFormat.evaluate(VF, may, str("MMMM"), str("xx-ZZ"))).isEqualTo(root);
		assertThat(dateFormat.evaluate(VF, may, str("MMMM"), str("not a tag"))).isEqualTo(root);
	}

	@Test
	void parseResultDatatypeFollowsThePatternFields() {
		assertThat(parseDate.evaluate(VF, str("2024-05-17"), str("yyyy-MM-dd"))).isEqualTo(date("2024-05-17"));
		assertThat(parseDate.evaluate(VF, str("10:11"), str("HH:mm"))).isEqualTo(time("10:11:00"));
		assertThat(parseDate.evaluate(VF, str("2024-05-17 10:11:12+05:30"), str("yyyy-MM-dd HH:mm:ssXXX")))
				.isEqualTo(dt("2024-05-17T10:11:12+05:30"));
		assertThat(parseDate.evaluate(VF, str("2024-05-17+02:00"), str("yyyy-MM-ddXXX")))
				.isEqualTo(date("2024-05-17+02:00"));
		assertThat(parseDate.evaluate(VF, str("10:11Z"), str("HH:mmXXX"))).isEqualTo(time("10:11:00Z"));
		assertThat(parseDate.evaluate(VF, str("2024-05-17 10:11:12.123456789"), str("yyyy-MM-dd HH:mm:ss.SSSSSSSSS")))
				.isEqualTo(dt("2024-05-17T10:11:12.123456789"));
		// a timezone never upgrades the result to xsd:dateTimeStamp
		Literal zoned = parseDate.evaluate(VF, str("2024-05-17 10:11:12Z"), str("yyyy-MM-dd HH:mm:ssXXX"));
		assertThat(zoned.getDatatype()).isEqualTo(CoreDatatype.XSD.DATETIME.getIri());
		assertThat(zoned).isEqualTo(dt("2024-05-17T10:11:12Z"));
	}

	@Test
	void missingFieldsAndImpossibleDates() {
		assertEvaluationError("no year", () -> parseDate.evaluate(VF, str("17.05"), str("dd.MM")));
		assertEvaluationError("year only", () -> parseDate.evaluate(VF, str("2024"), str("yyyy")));
		assertEvaluationError("day 32", () -> parseDate.evaluate(VF, str("2024-02-32"), str("yyyy-MM-dd")));
		assertEvaluationError("month 13", () -> parseDate.evaluate(VF, str("2024-13-01"), str("yyyy-MM-dd")));
		assertEvaluationError("minute 60", () -> parseDate.evaluate(VF, str("10:60"), str("HH:mm")));
		// the parser uses java.time's STRICT resolver: a day beyond the end of the month and the hour 24 are rejected
		// instead of being clamped to the last valid day or resolved to midnight
		assertEvaluationError("30 February", () -> parseDate.evaluate(VF, str("2024-02-30"), str("yyyy-MM-dd")));
		assertEvaluationError("29 February in a non-leap year",
				() -> parseDate.evaluate(VF, str("2023-02-29"), str("yyyy-MM-dd")));
		assertEvaluationError("24:00", () -> parseDate.evaluate(VF, str("24:00"), str("HH:mm")));
	}

	@Test
	void surroundingGarbageIsAnEvaluationError() {
		for (String text : List.of("2024-05-17xyz", "2024-05-17 ", " 2024-05-17", "2024-05-17T00:00", "x2024-05-17",
				"")) {
			assertEvaluationError("'" + text + "'", () -> parseDate.evaluate(VF, str(text), str("yyyy-MM-dd")));
		}
	}

	@Test
	void concurrentCallsWithSharedAndDistinctPatterns() throws Exception {
		int threads = 16;
		int iterations = 250;
		Literal value = dt("2024-05-17T10:11:12.345+02:00");
		String shared = "yyyy-MM-dd'T'HH:mm:ss.SSSXXX";
		Literal sharedExpected = dateFormat.evaluate(VF, value, str(shared));
		String[] distinct = new String[threads];
		Literal[] distinctExpected = new Literal[threads];
		for (int i = 0; i < threads; i++) {
			distinct[i] = "'t" + i + "' dd.MM.yyyy HH:mm:ss";
			distinctExpected[i] = dateFormat.evaluate(VF, value, str(distinct[i]));
		}
		ExecutorService pool = Executors.newFixedThreadPool(threads + 1);
		try {
			CountDownLatch start = new CountDownLatch(1);
			List<Future<Void>> futures = new ArrayList<>();
			for (int i = 0; i < threads; i++) {
				int id = i;
				futures.add(pool.submit((Callable<Void>) () -> {
					start.await();
					for (int n = 0; n < iterations; n++) {
						assertThat(dateFormat.evaluate(VF, value, str(shared))).isEqualTo(sharedExpected);
						assertThat(dateFormat.evaluate(VF, value, str(distinct[id]))).isEqualTo(distinctExpected[id]);
						assertThat(parseDate.evaluate(VF, sharedExpected, str(shared))).isEqualTo(value);
						assertThat(parseDate.evaluate(VF, distinctExpected[id], str(distinct[id])))
								.isEqualTo(dt("2024-05-17T10:11:12"));
					}
					return null;
				}));
			}
			// churns through more distinct patterns than the formatter cache holds, forcing evictions mid-flight
			futures.add(pool.submit((Callable<Void>) () -> {
				start.await();
				for (int n = 0; n < 1200; n++) {
					assertThat(dateFormat.evaluate(VF, value, str("'c" + n + "' yyyy")))
							.isEqualTo(str("c" + n + " 2024"));
				}
				return null;
			}));
			start.countDown();
			for (Future<Void> future : futures) {
				try {
					future.get(2, TimeUnit.MINUTES);
				} catch (ExecutionException e) {
					throw new AssertionError("concurrent dateFormat/parseDate call failed", e.getCause());
				}
			}
		} finally {
			pool.shutdownNow();
		}
	}
}
